apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/styles.css
+:root{
+  --red-700:#C41E3A;
+  --red-800:#a5182f;
+  --navy-800:#1B3A5C;
+  --ink-900:#0b1220;
+  --ink-700:#22314a;
+  --muted-600:#5b667a;
+  --surface-0:#ffffff;
+  --surface-50:#f7f7f8;
+  --surface-100:#f2f3f5;
+  --border-200:#e5e7eb;
+  --shadow:0 12px 30px rgba(11,18,32,.12);
+
+  --radius-16:16px;
+  --radius-12:12px;
+  --radius-10:10px;
+  --radius-8:8px;
+
+  --max:1120px;
+  --focus:0 0 0 3px rgba(27,58,92,.25);
+
+  --font-sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
+  --font-body: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial;
+}
+
+*{box-sizing:border-box}
+html{scroll-behavior:smooth}
+body{
+  margin:0;
+  font-family:var(--font-body);
+  color:var(--ink-900);
+  background:var(--surface-0);
+  line-height:1.55;
+}
+img{max-width:100%;display:block}
+a{color:inherit}
+
+.skip-link{
+  position:absolute;
+  left:-999px;
+  top:8px;
+  background:var(--surface-0);
+  border:1px solid var(--border-200);
+  padding:10px 12px;
+  border-radius:999px;
+  z-index:9999;
+}
+.skip-link:focus{left:12px;box-shadow:var(--focus)}
+
+.container{max-width:var(--max);margin:0 auto;padding:0 20px}
+
+.pill{
+  display:inline-flex;
+  align-items:center;
+  gap:10px;
+  padding:7px 12px;
+  border:1px solid rgba(255,255,255,.25);
+  border-radius:999px;
+  color:rgba(255,255,255,.92);
+  background:rgba(255,255,255,.08);
+  backdrop-filter: blur(6px);
+}
+.pill b{color:#fff}
+
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap:10px;
+  padding:12px 16px;
+  border-radius:999px;
+  border:1px solid transparent;
+  font-weight:700;
+  letter-spacing:.01em;
+  cursor:pointer;
+  text-decoration:none;
+  transition: transform .08s ease, background .2s ease, border-color .2s ease, color .2s ease;
+}
+.btn:active{transform:translateY(1px)}
+.btn:focus-visible{outline:none;box-shadow:var(--focus)}
+
+.btn-primary{background:var(--red-700);color:#fff}
+.btn-primary:hover{background:var(--red-800)}
+
+.btn-secondary{background:rgba(255,255,255,.14);color:#fff;border-color:rgba(255,255,255,.32)}
+.btn-secondary:hover{background:rgba(255,255,255,.22)}
+
+.btn-ghost{background:transparent;border-color:var(--border-200);color:var(--ink-900)}
+.btn-ghost:hover{background:var(--surface-50)}
+
+.btn-link{background:transparent;border-color:transparent;color:var(--navy-800);padding:10px 12px;border-radius:10px}
+.btn-link:hover{background:rgba(27,58,92,.06)}
+
+.badge{
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+  font-weight:700;
+  font-size:12px;
+  padding:6px 10px;
+  border-radius:999px;
+  background:rgba(196,30,58,.08);
+  color:var(--red-700);
+}
+
+.sr-only{
+  position:absolute;
+  width:1px;
+  height:1px;
+  padding:0;
+  margin:-1px;
+  overflow:hidden;
+  clip:rect(0,0,0,0);
+  white-space:nowrap;
+  border:0;
+}
+
+/* Header */
+.site-header{
+  position:sticky;
+  top:0;
+  z-index:50;
+  background:rgba(255,255,255,.86);
+  backdrop-filter: blur(10px);
+  border-bottom:1px solid var(--border-200);
+}
+.header-inner{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  padding:14px 0;
+  gap:14px;
+}
+.brand{
+  display:flex;
+  align-items:center;
+  gap:10px;
+  text-decoration:none;
+  white-space:nowrap;
+}
+.mark{
+  width:36px;height:36px;border-radius:10px;
+  background:conic-gradient(from 140deg, var(--red-700), #ff7a8a, var(--navy-800), var(--red-700));
+  box-shadow: 0 10px 18px rgba(196,30,58,.18);
+}
+.brand-text{display:flex;flex-direction:column;line-height:1.1}
+.brand-text strong{font-size:14px;letter-spacing:.02em}
+.brand-text span{font-size:12px;color:var(--muted-600)}
+
+.utility{
+  display:flex;
+  gap:12px;
+  align-items:center;
+  color:var(--muted-600);
+  font-size:13px;
+}
+.utility a{text-decoration:none;padding:6px 8px;border-radius:8px}
+.utility a:hover{background:var(--surface-50);color:var(--ink-900)}
+
+.nav{
+  display:flex;
+  align-items:center;
+  gap:8px;
+}
+.nav a{
+  text-decoration:none;
+  color:var(--ink-700);
+  font-weight:650;
+  padding:10px 12px;
+  border-radius:999px;
+}
+.nav a:hover{background:var(--surface-50);color:var(--ink-900)}
+
+.header-actions{display:flex;align-items:center;gap:10px}
+
+.menu-btn{
+  display:none;
+  width:44px;height:44px;
+  border-radius:999px;
+  border:1px solid var(--border-200);
+  background:var(--surface-0);
+}
+.menu-btn:focus-visible{outline:none;box-shadow:var(--focus)}
+
+.menu-icon{
+  width:18px;height:14px;margin:0 auto;position:relative;
+}
+.menu-icon span{
+  position:absolute;left:0;right:0;height:2px;background:var(--ink-900);border-radius:2px;
+}
+.menu-icon span:nth-child(1){top:0}
+.menu-icon span:nth-child(2){top:6px}
+.menu-icon span:nth-child(3){top:12px}
+
+/* Mobile drawer */
+.drawer-backdrop{
+  position:fixed;inset:0;background:rgba(11,18,32,.45);
+  opacity:0;pointer-events:none;transition:opacity .22s ease;
+  z-index:60;
+}
+.drawer{
+  position:fixed;top:0;right:0;height:100%;width:min(360px, 90vw);
+  background:var(--surface-0);
+  transform:translateX(105%);
+  transition:transform .22s ease;
+  z-index:70;
+  box-shadow: var(--shadow);
+  display:flex;flex-direction:column;
+}
+.drawer header{display:flex;align-items:center;justify-content:space-between;padding:16px 16px 10px;border-bottom:1px solid var(--border-200)}
+.drawer nav{display:flex;flex-direction:column;padding:10px 10px 18px;gap:4px}
+.drawer nav a{padding:12px 12px;border-radius:12px;text-decoration:none;color:var(--ink-900);font-weight:700}
+.drawer nav a:hover{background:var(--surface-50)}
+.drawer .drawer-actions{padding:14px 16px;border-top:1px solid var(--border-200);display:grid;gap:10px}
+
+body.drawer-open{overflow:hidden}
+body.drawer-open .drawer-backdrop{opacity:1;pointer-events:auto}
+body.drawer-open .drawer{transform:translateX(0)}
+
+/* Hero */
+.hero{
+  position:relative;
+  padding:54px 0 34px;
+  background:
+    radial-gradient(1200px 480px at 20% 10%, rgba(196,30,58,.25), transparent 55%),
+    radial-gradient(900px 420px at 80% 0%, rgba(27,58,92,.20), transparent 55%),
+    linear-gradient(180deg, #0b1220 0%, #141b2a 60%, #0b1220 100%);
+  color:#fff;
+  overflow:hidden;
+}
+.hero-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:34px;align-items:center}
+.hero h1{font-size:clamp(34px, 4.2vw, 54px);line-height:1.04;margin:12px 0 12px;letter-spacing:-.02em}
+.hero p{margin:0 0 18px;color:rgba(255,255,255,.88);font-size:clamp(16px, 1.4vw, 18px)}
+.hero-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:18px}
+
+.hero-card{
+  background:rgba(255,255,255,.08);
+  border:1px solid rgba(255,255,255,.18);
+  border-radius:var(--radius-16);
+  padding:16px;
+  backdrop-filter: blur(10px);
+}
+.hero-card img{border-radius:14px;border:1px solid rgba(255,255,255,.12)}
+.hero-card .caption{margin-top:10px;color:rgba(255,255,255,.82);font-size:13px}
+
+/* Sections */
+section{scroll-margin-top:86px}
+.section{padding:56px 0;background:var(--surface-0)}
+.section.alt{background:var(--surface-50)}
+.section h2{font-size:clamp(26px, 2.6vw, 34px);margin:0 0 12px;letter-spacing:-.02em}
+.section .lede{color:var(--muted-600);margin:0 0 18px;max-width:72ch}
+
+.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:24px}
+.card{
+  background:var(--surface-0);
+  border:1px solid var(--border-200);
+  border-radius:var(--radius-16);
+  padding:18px;
+  box-shadow: 0 1px 0 rgba(11,18,32,.03);
+}
+.card h3{margin:0 0 10px;font-size:18px}
+.card p{margin:0;color:var(--muted-600)}
+
+/* Mission */
+.mission{
+  display:grid;
+  grid-template-columns:1.2fr .8fr;
+  gap:24px;
+  align-items:start;
+}
+.mission .card{padding:22px}
+.principles{display:grid;gap:12px}
+.principles .pill{border-color:var(--border-200);background:var(--surface-0);color:var(--ink-700)}
+.principles .pill b{color:var(--ink-900)}
+
+/* Stats */
+.stats{
+  display:grid;
+  grid-template-columns:repeat(4, 1fr);
+  gap:14px;
+  margin-top:18px;
+}
+.stat{
+  border-radius:var(--radius-16);
+  border:1px solid var(--border-200);
+  background:linear-gradient(180deg, #fff, #fbfbfc);
+  padding:18px;
+  min-height:108px;
+}
+.stat .value{font-size:clamp(28px, 3.2vw, 40px);font-weight:850;letter-spacing:-.03em;color:var(--navy-800)}
+.stat .label{color:var(--muted-600);font-weight:650;margin-top:4px}
+.stat .accent{display:inline-flex;align-items:center;gap:8px;color:var(--red-700);font-weight:800;font-size:12px;margin-bottom:6px}
+
+/* Programs accordion */
+.accordion{display:grid;gap:10px;margin-top:16px}
+.acc-item{
+  border:1px solid var(--border-200);
+  border-radius:var(--radius-16);
+  overflow:hidden;
+  background:var(--surface-0);
+}
+.acc-trigger{
+  width:100%;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:14px;
+  padding:16px 16px;
+  background:transparent;
+  border:0;
+  cursor:pointer;
+  text-align:left;
+}
+.acc-trigger:focus-visible{outline:none;box-shadow:var(--focus)}
+.acc-title{font-size:16px;font-weight:850;letter-spacing:-.01em}
+.acc-kicker{display:block;font-size:13px;color:var(--muted-600);font-weight:650;margin-top:3px}
+.acc-icon{
+  width:34px;height:34px;border-radius:999px;
+  display:grid;place-items:center;
+  border:1px solid var(--border-200);
+  background:var(--surface-50);
+  flex:0 0 auto;
+  transition: transform .2s ease;
+}
+.acc-panel{
+  max-height:0;
+  overflow:hidden;
+  transition:max-height .26s ease;
+}
+.acc-panel-inner{padding:0 16px 16px;color:var(--muted-600)}
+.acc-item[data-open="true"] .acc-icon{transform:rotate(180deg)}
+
+/* Get involved */
+.involved{display:grid;grid-template-columns:repeat(3, 1fr);gap:14px;margin-top:16px}
+.involved .card{display:flex;flex-direction:column;gap:12px}
+.involved .card .btn{align-self:flex-start}
+
+/* News carousel */
+.carousel{
+  margin-top:16px;
+  position:relative;
+}
+.carousel-viewport{
+  overflow:hidden;
+  border-radius:var(--radius-16);
+}
+.carousel-track{
+  display:flex;
+  gap:14px;
+  padding:2px;
+  transform:translateX(0);
+  transition: transform .35s ease;
+}
+.news-card{
+  flex:0 0 calc((100% - 28px) / 3);
+  background:var(--surface-0);
+  border:1px solid var(--border-200);
+  border-radius:var(--radius-16);
+  overflow:hidden;
+  display:flex;
+  flex-direction:column;
+  min-height:320px;
+}
+.news-card img{height:170px;object-fit:cover}
+.news-card .body{padding:14px 14px 16px}
+.news-card h3{margin:0 0 8px;font-size:16px;letter-spacing:-.01em}
+.news-card p{margin:0;color:var(--muted-600)}
+
+.carousel-controls{display:flex;gap:10px;align-items:center;margin-top:12px}
+.icon-btn{
+  width:44px;height:44px;border-radius:999px;border:1px solid var(--border-200);
+  background:var(--surface-0);
+  display:grid;place-items:center;
+  cursor:pointer;
+}
+.icon-btn:hover{background:var(--surface-50)}
+.icon-btn:focus-visible{outline:none;box-shadow:var(--focus)}
+.icon-btn[disabled]{opacity:.45;cursor:not-allowed}
+.carousel-status{color:var(--muted-600);font-weight:650;font-size:13px}
+
+/* Donate CTA */
+.donate{
+  display:grid;
+  grid-template-columns:1.1fr .9fr;
+  gap:18px;
+  align-items:start;
+}
+.donate .card{padding:22px}
+.impact-table{width:100%;border-collapse:collapse;margin-top:12px}
+.impact-table th,.impact-table td{padding:10px 10px;border-bottom:1px solid var(--border-200);text-align:left}
+.impact-table th{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted-600)}
+.impact-table td{color:var(--ink-700);font-weight:650}
+.fineprint{margin-top:12px;color:var(--muted-600);font-size:13px}
+
+/* Footer */
+footer{
+  padding:44px 0;
+  background:#0b1220;
+  color:rgba(255,255,255,.9);
+}
+.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:18px}
+.footer-grid h3{margin:0 0 10px;font-size:13px;text-transform:uppercase;letter-spacing:.12em;color:rgba(255,255,255,.75)}
+.footer-grid a{display:block;text-decoration:none;color:rgba(255,255,255,.9);padding:6px 0}
+.footer-grid a:hover{color:#fff;text-decoration:underline}
+.footer-brand{display:flex;align-items:center;gap:12px;margin-bottom:10px}
+.footer-brand .mark{width:40px;height:40px;border-radius:12px}
+.footer-note{color:rgba(255,255,255,.72);font-size:13px;max-width:58ch}
+.footer-bottom{margin-top:26px;padding-top:18px;border-top:1px solid rgba(255,255,255,.14);display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between}
+.social{display:flex;gap:10px;flex-wrap:wrap}
+.social a{padding:8px 10px;border-radius:999px;border:1px solid rgba(255,255,255,.18);text-decoration:none}
+.social a:hover{background:rgba(255,255,255,.08)}
+
+/* Modal */
+.modal-backdrop{
+  position:fixed;inset:0;background:rgba(11,18,32,.52);
+  opacity:0;pointer-events:none;transition:opacity .18s ease;
+  z-index:90;
+}
+.modal{
+  position:fixed;left:50%;top:50%;transform:translate(-50%,-46%);
+  width:min(760px, 92vw);
+  background:var(--surface-0);
+  border:1px solid var(--border-200);
+  border-radius:18px;
+  box-shadow:var(--shadow);
+  opacity:0;pointer-events:none;transition: opacity .18s ease, transform .18s ease;
+  z-index:100;
+}
+.modal header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:18px 18px 10px;border-bottom:1px solid var(--border-200)}
+.modal header h2{margin:0;font-size:18px;letter-spacing:-.01em}
+.modal header p{margin:6px 0 0;color:var(--muted-600);font-size:13px}
+.modal .content{padding:16px 18px 18px}
+.modal .grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}
+
+.amounts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
+.amount-btn{
+  border:1px solid var(--border-200);
+  background:var(--surface-0);
+  border-radius:14px;
+  padding:14px 12px;
+  cursor:pointer;
+  text-align:left;
+}
+.amount-btn strong{display:block;font-size:16px;letter-spacing:-.01em}
+.amount-btn span{display:block;margin-top:4px;color:var(--muted-600);font-size:12px}
+.amount-btn:hover{background:var(--surface-50)}
+.amount-btn[aria-pressed="true"]{border-color:rgba(196,30,58,.5);box-shadow:0 0 0 3px rgba(196,30,58,.14)}
+
+.field{display:grid;gap:6px;margin-top:10px}
+.field label{font-weight:750;font-size:13px;color:var(--ink-700)}
+.field input,.field select{
+  height:44px;border-radius:12px;border:1px solid var(--border-200);
+  padding:0 12px;font:inherit;
+}
+.field input:focus-visible,.field select:focus-visible{outline:none;box-shadow:var(--focus)}
+
+.modal-actions{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between;margin-top:14px}
+.hint{color:var(--muted-600);font-size:12px}
+
+body.modal-open{overflow:hidden}
+body.modal-open .modal-backdrop{opacity:1;pointer-events:auto}
+body.modal-open .modal{opacity:1;pointer-events:auto;transform:translate(-50%,-50%)}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns:1fr;gap:18px}
+  .mission{grid-template-columns:1fr}
+  .donate{grid-template-columns:1fr}
+  .footer-grid{grid-template-columns:1fr 1fr}
+  .stats{grid-template-columns:repeat(2,1fr)}
+  .involved{grid-template-columns:1fr}
+  .news-card{flex:0 0 calc((100% - 14px) / 2)}
+}
+
+@media (max-width: 760px){
+  .nav{display:none}
+  .utility{display:none}
+  .menu-btn{display:inline-grid;place-items:center}
+  .header-inner{padding:12px 0}
+  .hero{padding:44px 0 28px}
+  .amounts{grid-template-columns:repeat(2,1fr)}
+  .modal .grid{grid-template-columns:1fr}
+  .news-card{flex:0 0 100%}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{scroll-behavior:auto}
+  .carousel-track{transition:none}
+  .acc-panel{transition:none}
+  .drawer,.drawer-backdrop,.modal,.modal-backdrop{transition:none}
+}
+
*** End Patch
PATCH

